from abc import ABC, abstractmethod


class Bino(ABC):
    @abstractmethod
    def oylik(self):
        pass


class Kvartira(Bino):
    def __init__(self, maydon, xona):
        self.maydon = maydon
        self.xona = xona

    def oylik(self):
        return self.maydon * 15000


class Ofis(Bino):
    def __init__(self, maydon):
        self.maydon = maydon

    def oylik(self):
        return self.maydon * 25000


n = int(input())
binolar = []
for _ in range(n):
    q = input().split()
    if q[0] == "kvartira":
        binolar.append(Kvartira(int(q[1]), int(q[2])))
    else:
        binolar.append(Ofis(int(q[1])))

jami = 0
for b in binolar:
    print(b.oylik())
    jami += b.oylik()
print(jami)

