import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    abstract static class Bino {
        abstract long oylik();
    }

    static class Kvartira extends Bino {
        long maydon, xona;

        Kvartira(long maydon, long xona) {
            this.maydon = maydon;
            this.xona = xona;
        }

        @Override
        long oylik() {
            return maydon * 15000;
        }
    }

    static class Ofis extends Bino {
        long maydon;

        Ofis(long maydon) {
            this.maydon = maydon;
        }

        @Override
        long oylik() {
            return maydon * 25000;
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        List<Bino> binolar = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String tur = in.next();
            if (tur.equals("kvartira")) binolar.add(new Kvartira(in.nextLong(), in.nextLong()));
            else binolar.add(new Ofis(in.nextLong()));
        }

        long jami = 0;
        for (Bino b : binolar) {
            System.out.println(b.oylik());
            jami += b.oylik();
        }
        System.out.println(jami);
    }
}

