#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;

class Bino {
public:
    virtual ~Bino() = default;
    virtual long long oylik() const = 0;
};

class Kvartira : public Bino {
    long long maydon, xona;

public:
    Kvartira(long long maydon, long long xona) : maydon(maydon), xona(xona) {}

    long long oylik() const override {
        return maydon * 15000;
    }
};

class Ofis : public Bino {
    long long maydon;

public:
    Ofis(long long maydon) : maydon(maydon) {}

    long long oylik() const override {
        return maydon * 25000;
    }
};

int main() {
    int n;
    cin >> n;
    vector<unique_ptr<Bino>> binolar;
    for (int i = 0; i < n; i++) {
        string tur;
        long long maydon, xona;
        cin >> tur >> maydon;
        if (tur == "kvartira") {
            cin >> xona;
            binolar.push_back(make_unique<Kvartira>(maydon, xona));
        } else {
            binolar.push_back(make_unique<Ofis>(maydon));
        }
    }

    long long jami = 0;
    for (const auto& b : binolar) {
        cout << b->oylik() << endl;
        jami += b->oylik();
    }
    cout << jami << endl;
    return 0;
}

